        confirmLeave: false,
        toasts: true,
        playingTitle: true,
        modernUI: false,
        flStudioUI: false,
        uiSounds: true,
        uiSoundVolume: 0.35,
        extraShortcuts: true,
        uiScale: 100,
        reduceMotion: false,
        openPluginOnLoad: true,
        welcomeSeen: false,
